{
  "name": "studystack",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "concurrently -k \"vite\" \"node server/index.mjs\"",
    "build": "vite build",
    "preview": "vite preview",
    "server": "node server/index.mjs",
    "smoke": "node scripts/smoke.mjs"
  },
  "dependencies": {
    "concurrently": "^9.1.2",
    "cors": "^2.8.5",
    "express": "^4.21.2",
    "seekdb-js": "1.4.0"
  },
  "devDependencies": {
    "@types/cors": "^2.8.17",
    "@types/express": "^5.0.0",
    "typescript": "^5.7.3",
    "vite": "^6.3.5"
  }
}

import { defineConfig } from 'vite';

export default defineConfig({
  root: '.',
  publicDir: 'public',
  server: {
    port: 5173,
    proxy: {
      '/api': {
        target: 'http://localhost:8787',
        changeOrigin: true,
      },
      '/models': {
        target: 'http://localhost:8787',
        changeOrigin: true,
      },
    },
  },
  worker: {
    format: 'es',
  },
  build: {
    outDir: 'dist',
    target: 'esnext',
  },
});

import { SeekdbClient } from 'seekdb-js';

const DB_PATH = process.env.SEEKB_PATH || './data/study.db';

let client;

export async function getClient() {
  if (!client) {
    client = new SeekdbClient({ path: DB_PATH });
  }
  return client;
}

export async function createCollection(courseId) {
  const c = await getClient();
  const collection = await c.createCollection(courseId, {
    fulltextIndex: { type: 'ngram', ngram_token_size: 2 },
    vectorIndex: {
      hnsw: { dimension: 512, distance: 'cosine' },
      embeddingFunction: null,
    },
    embeddingFunction: null,
  });
  return collection;
}

export async function getCollection(courseId) {
  const c = await getClient();
  return await c.getCollection(courseId);
}

export async function listCollections() {
  const c = await getClient();
  const list = await c.listCollections();
  return list || [];
}

export async function deleteCollection(courseId) {
  const c = await getClient();
  await c.deleteCollection(courseId);
}

export async function upsertDocuments(courseId, docs) {
  const col = await getCollection(courseId);
  await col.upsert(docs);
  await col.refresh_index();
}

export async function hybridSearch(courseId, queryText, queryVector, topK = 10) {
  const c = await getClient();
  const col = await getCollection(courseId);
  const tableName = `c$v2$${col.collectionId}`;

  const searchParm = {
    text: {
      query: queryText,
      fields: ['text'],
    },
    vector: {
      field: 'embedding',
      query: queryVector,
      topK,
    },
    fusion: {
      method: 'rrf',
      k: 60,
    },
  };

  const parmJson = JSON.stringify(searchParm);
  await c.execute('SET @search_parm = ?', [parmJson]);

  const sqlResult = await c.execute(
    `SELECT DBMS_HYBRID_SEARCH.GET_SQL('${tableName}', @search_parm) AS sql_text`
  );

  let generatedSql;
  if (Array.isArray(sqlResult) && sqlResult.length > 0) {
    generatedSql = sqlResult[0].sql_text || sqlResult[0].SQL_TEXT || sqlResult[0];
  } else if (typeof sqlResult === 'string') {
    generatedSql = sqlResult;
  } else {
    throw new Error('Failed to get hybrid search SQL');
  }

  generatedSql = generatedSql.replace(/APPROXIMATE\s+/gi, '');

  const results = await c.execute(generatedSql);
  return results;
}

export async function ensureReviewTable() {
  const c = await getClient();
  await c.execute(`
    CREATE TABLE IF NOT EXISTS review_progress (
      id VARCHAR(255) PRIMARY KEY,
      collection_id VARCHAR(255) NOT NULL,
      chunk_id VARCHAR(255) NOT NULL,
      text TEXT,
      file_name VARCHAR(512),
      mastery INTEGER DEFAULT 0,
      review_count INTEGER DEFAULT 0,
      last_reviewed DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
}

export async function upsertReviewProgress(entry) {
  const c = await getClient();
  await ensureReviewTable();
  const { id, collection_id, chunk_id, text, file_name } = entry;
  await c.execute(
    `INSERT INTO review_progress (id, collection_id, chunk_id, text, file_name, mastery, review_count, last_reviewed)
     VALUES (?, ?, ?, ?, ?, 0, 0, CURRENT_TIMESTAMP)
     ON DUPLICATE KEY UPDATE last_reviewed = CURRENT_TIMESTAMP`,
    [id, collection_id, chunk_id, text || '', file_name || '']
  );
}

export async function updateMastery(id, mastery) {
  const c = await getClient();
  await ensureReviewTable();
  await c.execute(
    `UPDATE review_progress SET mastery = ?, review_count = review_count + 1, last_reviewed = CURRENT_TIMESTAMP WHERE id = ?`,
    [mastery, id]
  );
}

export async function getWeakPoints(courseId, limit = 5) {
  const c = await getClient();
  await ensureReviewTable();
  const rows = await c.execute(
    `SELECT * FROM review_progress WHERE collection_id = ? ORDER BY mastery ASC, review_count DESC LIMIT ?`,
    [courseId, limit]
  );
  return rows || [];
}

export async function getAllProgress(courseId) {
  const c = await getClient();
  await ensureReviewTable();
  const rows = await c.execute(
    `SELECT * FROM review_progress WHERE collection_id = ? ORDER BY last_reviewed DESC`,
    [courseId]
  );
  return rows || [];
}

import express from 'express';
import cors from 'cors';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import {
  createCollection,
  getCollection,
  listCollections,
  deleteCollection,
  upsertDocuments,
  hybridSearch,
  upsertReviewProgress,
  updateMastery,
  getWeakPoints,
  getAllProgress,
} from './seekdb.mjs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = 8787;

app.use(cors());
app.use(express.json({ limit: '50mb' }));
app.use('/models', express.static(join(__dirname, '..', 'models')));

app.get('/api/health', (_req, res) => {
  res.json({ status: 'ok' });
});

app.post('/api/collections', async (req, res) => {
  try {
    const { courseId } = req.body;
    if (!courseId || typeof courseId !== 'string') {
      return res.status(400).json({ error: '缺少 courseId' });
    }
    await createCollection(courseId);
    res.json({ ok: true, courseId });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/collections', async (_req, res) => {
  try {
    const list = await listCollections();
    const result = [];
    for (const col of list) {
      try {
        const full = await getCollection(col.name || col);
        const name = col.name || col;
        let docCount = 0;
        let chunkCount = 0;
        try {
          const docs = await full.count?.() ?? 0;
          docCount = typeof docs === 'number' ? docs : 0;
          chunkCount = docCount;
        } catch { /* empty collection */ }
        result.push({
          courseId: name,
          collectionId: full.collectionId,
          docCount,
          chunkCount,
          dimension: 512,
        });
      } catch {
        const name = col.name || col;
        result.push({ courseId: name, collectionId: name, docCount: 0, chunkCount: 0, dimension: 512 });
      }
    }
    res.json(result);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.delete('/api/collections/:courseId', async (req, res) => {
  try {
    await deleteCollection(req.params.courseId);
    res.json({ ok: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/import', async (req, res) => {
  try {
    const { courseId, chunks } = req.body;
    if (!courseId || !Array.isArray(chunks)) {
      return res.status(400).json({ error: '缺少 courseId 或 chunks' });
    }
    if (chunks.length === 0) {
      return res.json({ ok: true, imported: 0 });
    }
    const docs = chunks.map((c) => ({
      id: c.id,
      text: c.text,
      embedding: c.embedding,
      file_name: c.fileName || '',
      chunk_index: c.chunkIndex ?? 0,
    }));
    await upsertDocuments(courseId, docs);
    res.json({ ok: true, imported: docs.length });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/search', async (req, res) => {
  try {
    const { courseId, query, vector, topK } = req.body;
    if (!courseId || !query || !vector) {
      return res.status(400).json({ error: '缺少 courseId / query / vector' });
    }
    const results = await hybridSearch(courseId, query, vector, topK || 10);
    res.json({ results: Array.isArray(results) ? results : [] });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/review/add', async (req, res) => {
  try {
    const { courseId, chunkId, text, fileName } = req.body;
    if (!courseId || !chunkId) {
      return res.status(400).json({ error: '缺少 courseId 或 chunkId' });
    }
    await upsertReviewProgress({
      id: `${courseId}::${chunkId}`,
      collection_id: courseId,
      chunk_id: chunkId,
      text,
      file_name: fileName,
    });
    res.json({ ok: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/review/mastery', async (req, res) => {
  try {
    const { id, mastery } = req.body;
    if (!id || mastery === undefined) {
      return res.status(400).json({ error: '缺少 id 或 mastery' });
    }
    await updateMastery(id, mastery);
    res.json({ ok: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/review/weak/:courseId', async (req, res) => {
  try {
    const rows = await getWeakPoints(req.params.courseId, 5);
    res.json(rows);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/review/all/:courseId', async (req, res) => {
  try {
    const rows = await getAllProgress(req.params.courseId);
    res.json(rows);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.listen(PORT, () => {
  console.log(`StudyStack API server running on http://localhost:${PORT}`);
});

:root {
  --bg: #0f1117;
  --bg-card: #1a1d27;
  --bg-input: #232735;
  --border: #2e3345;
  --text: #e4e6ef;
  --text-dim: #8b90a5;
  --accent: #5b8def;
  --accent-hover: #7aa2f7;
  --danger: #f7768e;
  --success: #9ece6a;
  --warn: #e0af68;
  --radius: 8px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: -apple-system, 'PingFang SC', 'Microsoft YaHei', sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

#app {
  max-width: 960px;
  margin: 0 auto;
  padding: 20px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
}

header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

#status-bar {
  font-size: 0.85rem;
  color: var(--text-dim);
  background: var(--bg-card);
  padding: 4px 12px;
  border-radius: var(--radius);
}

nav {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}

.nav-btn {
  background: var(--bg-card);
  color: var(--text-dim);
  border: 1px solid var(--border);
  padding: 8px 18px;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.2s;
}

.nav-btn:hover { color: var(--text); border-color: var(--accent); }
.nav-btn.active { background: var(--accent); color: #fff; border-color: var(--accent); }

.tab-content { display: none; }
.tab-content.active { display: block; }

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 12px;
}

.card h3 { margin-bottom: 8px; font-size: 1rem; }

input[type="text"], input[type="number"], select, textarea {
  width: 100%;
  background: var(--bg-input);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 0.9rem;
  outline: none;
  transition: border 0.2s;
}

input:focus, select:focus, textarea:focus { border-color: var(--accent); }

button.primary {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 8px 20px;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 0.9rem;
  transition: background 0.2s;
}

button.primary:hover { background: var(--accent-hover); }
button.primary:disabled { opacity: 0.5; cursor: not-allowed; }

button.danger {
  background: transparent;
  color: var(--danger);
  border: 1px solid var(--danger);
  padding: 6px 14px;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 0.85rem;
}

button.danger:hover { background: var(--danger); color: #fff; }

button.small {
  padding: 4px 12px;
  font-size: 0.8rem;
  border-radius: 6px;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--bg-input);
  color: var(--text);
}

button.small:hover { border-color: var(--accent); }

.row { display: flex; gap: 10px; align-items: center; margin-bottom: 10px; }
.row > * { flex: 1; }

.label { font-size: 0.85rem; color: var(--text-dim); margin-bottom: 4px; }

.progress-bar {
  height: 6px;
  background: var(--bg-input);
  border-radius: 3px;
  overflow: hidden;
  margin-top: 8px;
}

.progress-bar .fill {
  height: 100%;
  background: var(--accent);
  transition: width 0.3s;
}

.search-result {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
  margin-bottom: 10px;
}

.search-result .score {
  font-size: 0.8rem;
  color: var(--accent);
  margin-bottom: 6px;
}

.search-result .text {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--text);
}

.search-result .meta {
  font-size: 0.8rem;
  color: var(--text-dim);
  margin-top: 6px;
}

.search-result .actions {
  margin-top: 8px;
  display: flex;
  gap: 6px;
}

mark {
  background: var(--warn);
  color: #000;
  border-radius: 2px;
  padding: 0 2px;
}

.mastery-btns { display: flex; gap: 6px; }

.mastery-btns button {
  padding: 4px 12px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.8rem;
  border: 1px solid var(--border);
  background: var(--bg-input);
  color: var(--text);
}

.mastery-btns button:hover { border-color: var(--accent); }
.mastery-btns button.selected-mastery-2 { background: var(--success); color: #fff; border-color: var(--success); }
.mastery-btns button.selected-mastery-1 { background: var(--warn); color: #000; border-color: var(--warn); }
.mastery-btns button.selected-mastery-0 { background: var(--danger); color: #fff; border-color: var(--danger); }

.weak-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.weak-item:last-child { border-bottom: none; }

.weak-item .info { flex: 1; }
.weak-item .info .text-preview { font-size: 0.85rem; color: var(--text); margin-bottom: 4px; }
.weak-item .info .meta-line { font-size: 0.75rem; color: var(--text-dim); }

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 0.75rem;
  font-weight: 600;
}

.badge-mastery-0 { background: var(--danger); color: #fff; }
.badge-mastery-1 { background: var(--warn); color: #000; }
.badge-mastery-2 { background: var(--success); color: #fff; }

.empty-hint {
  text-align: center;
  color: var(--text-dim);
  padding: 40px 0;
  font-size: 0.9rem;
}

.toast {
  position: fixed;
  bottom: 20px;
  right: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 20px;
  font-size: 0.85rem;
  color: var(--text);
  z-index: 999;
  animation: fadeIn 0.2s;
}

.toast.error { border-color: var(--danger); color: var(--danger); }
.toast.success { border-color: var(--success); color: var(--success); }

@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.config-row { display: flex; gap: 12px; margin-bottom: 10px; }
.config-row label { flex: 1; }
.config-row label span { display: block; font-size: 0.8rem; color: var(--text-dim); margin-bottom: 4px; }

.file-list { margin-top: 10px; }
.file-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 0;
  font-size: 0.85rem;
  color: var(--text-dim);
  border-bottom: 1px solid var(--border);
}

.collection-info {
  display: flex;
  gap: 16px;
  font-size: 0.8rem;
  color: var(--text-dim);
  margin-top: 6px;
}

.collection-info span { background: var(--bg-input); padding: 2px 8px; border-radius: 4px; }

const API_BASE = '/api';

async function request<T>(url: string, options?: RequestInit): Promise<T> {
  const res = await fetch(API_BASE + url, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  if (!res.ok) {
    const body = await res.json().catch(() => ({ error: res.statusText }));
    throw new Error(body.error || `HTTP ${res.status}`);
  }
  return res.json();
}

export interface CollectionInfo {
  courseId: string;
  collectionId: string;
  docCount: number;
  chunkCount: number;
  dimension: number;
}

export interface SearchResult {
  id: string;
  text: string;
  score: number;
  file_name?: string;
  chunk_index?: number;
  [key: string]: unknown;
}

export interface ReviewEntry {
  id: string;
  collection_id: string;
  chunk_id: string;
  text: string;
  file_name: string;
  mastery: number;
  review_count: number;
  last_reviewed: string;
}

export const api = {
  createCollection(courseId: string) {
    return request<{ ok: boolean }>('/collections', {
      method: 'POST',
      body: JSON.stringify({ courseId }),
    });
  },

  listCollections(): Promise<CollectionInfo[]> {
    return request<CollectionInfo[]>('/collections');
  },

  deleteCollection(courseId: string) {
    return request<{ ok: boolean }>(`/collections/${encodeURIComponent(courseId)}`, {
      method: 'DELETE',
    });
  },

  importChunks(courseId: string, chunks: Array<{
    id: string;
    text: string;
    embedding: number[];
    fileName: string;
    chunkIndex: number;
  }>) {
    return request<{ ok: boolean; imported: number }>('/import', {
      method: 'POST',
      body: JSON.stringify({ courseId, chunks }),
    });
  },

  search(courseId: string, query: string, vector: number[], topK = 10) {
    return request<{ results: SearchResult[] }>('/search', {
      method: 'POST',
      body: JSON.stringify({ courseId, query, vector, topK }),
    });
  },

  addReview(courseId: string, chunkId: string, text: string, fileName: string) {
    return request<{ ok: boolean }>('/review/add', {
      method: 'POST',
      body: JSON.stringify({ courseId, chunkId, text, fileName }),
    });
  },

  updateMastery(id: string, mastery: number) {
    return request<{ ok: boolean }>('/review/mastery', {
      method: 'POST',
      body: JSON.stringify({ id, mastery }),
    });
  },

  getWeakPoints(courseId: string): Promise<ReviewEntry[]> {
    return request<ReviewEntry[]>(`/review/weak/${encodeURIComponent(courseId)}`);
  },

  getAllProgress(courseId: string): Promise<ReviewEntry[]> {
    return request<ReviewEntry[]>(`/review/all/${encodeURIComponent(courseId)}`);
  },
};

import type { CollectionInfo, ReviewEntry } from './api';

export interface AppState {
  currentCourse: string | null;
  collections: CollectionInfo[];
  reviewProgress: Map<string, ReviewEntry>;
  lastSearchTime: { embed: number; search: number; total: number } | null;
  modelReady: boolean;
  importProgress: { current: number; total: number } | null;
}

const STORAGE_KEY = 'studystack_state';

export function loadState(): Partial<AppState> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return {
      currentCourse: parsed.currentCourse || null,
    };
  } catch {
    return {};
  }
}

export function saveState(state: AppState) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      currentCourse: state.currentCourse,
    }));
  } catch { /* quota exceeded */ }
}

export function setStatus(text: string) {
  const el = document.getElementById('status-bar');
  if (el) el.textContent = text;
}

export function showToast(message: string, type: 'info' | 'error' | 'success' = 'info') {
  const existing = document.querySelector('.toast');
  if (existing) existing.remove();

  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.textContent = message;
  document.body.appendChild(toast);
  setTimeout(() => toast.remove(), 3000);
}

import { pipeline, env } from '@xenova/transformers';

env.allowLocalModels = true;
env.localModelPath = '/models/';
env.allowRemoteModels = true;

let embedder: Awaited<ReturnType<typeof pipeline>> | null = null;

async function getModel() {
  if (!embedder) {
    embedder = await pipeline(
      'feature-extraction',
      'Xenova/bge-small-zh-v1.5',
      {
        dtype: 'q8',
        device: typeof navigator !== 'undefined' && (navigator as any).gpu ? 'webgpu' : 'wasm',
      }
    );
    try {
      await embedder('test');
    } catch {
      embedder = await pipeline(
        'feature-extraction',
        'Xenova/bge-small-zh-v1.5',
        { dtype: 'q8', device: 'wasm' }
      );
    }
  }
  return embedder;
}

self.onmessage = async (e: MessageEvent) => {
  const { id, type, texts } = e.data;
  try {
    if (type === 'embed') {
      const model = await getModel();
      const results: number[][] = [];
      for (const text of texts) {
        const output = await model(text, { pooling: 'cls' });
        results.push(Array.from(output.data));
      }
      (self as unknown as Worker).postMessage({ id, results });
    } else if (type === 'ready') {
      await getModel();
      (self as unknown as Worker).postMessage({ id, ready: true });
    }
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    (self as unknown as Worker).postMessage({ id, error: message });
  }
};

let worker: Worker | null = null;
let pendingCalls = new Map<number, { resolve: (v: unknown) => void; reject: (e: Error) => void }>();
let callId = 0;

function getWorker(): Worker {
  if (!worker) {
    worker = new Worker(new URL('./worker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = (e: MessageEvent) => {
      const { id, error } = e.data;
      const pending = pendingCalls.get(id);
      if (!pending) return;
      pendingCalls.delete(id);
      if (error) {
        pending.reject(new Error(error));
      } else {
        pending.resolve(e.data);
      }
    };
    worker.onerror = (e) => {
      console.error('Worker error:', e);
    };
  }
  return worker;
}

function call<T>(data: Record<string, unknown>): Promise<T> {
  return new Promise((resolve, reject) => {
    const id = ++callId;
    pendingCalls.set(id, {
      resolve: (v) => resolve(v as T),
      reject,
    });
    getWorker().postMessage({ id, ...data });
  });
}

export async function ensureModelReady(): Promise<void> {
  await call<{ ready: boolean }>({ type: 'ready' });
}

export async function embedTexts(texts: string[]): Promise<number[][]> {
  const result = await call<{ results: number[][] }>({ type: 'embed', texts });
  return result.results;
}

export async function embedSingle(text: string): Promise<number[]> {
  const results = await embedTexts([text]);
  return results[0];
}

