202	function splitIntoChunks(text: string, size: number, overlap: number): string[] {
203	  const sentences = text.match(/[^。！？.!?\n]+[。！？.!?\n]?/g) || [text];
204	  const chunks: string[] = [];
205	  let current = '';
206	  for (const sentence of sentences) {
207	    if (current.length + sentence.length > size && current.length > 0) {
208	      chunks.push(current.trim());
209	      const words = current.split(/\s+/);
210	      let keep = '';
211	      let keepLen = 0;
212	      for (let i = words.length - 1; i >= 0; i--) {
213	        if (keepLen + words[i].length > overlap) break;
214	        keep = words[i] + ' ' + keep;
215	        keepLen += words[i].length + 1;
216	      }
217	      current = keep.trim() + sentence;
218	    } else {
219	      current += sentence;
220	    }
221	  }
222	  if (current.trim()) chunks.push(current.trim());
223	  return chunks;
224	}
