226	interface ParsedFile {
227	  fileName: string;
228	  chunks: Array<{ id: string; text: string; fileName: string; chunkIndex: number }>;
229	}
230	
231	function parseFile(fileName: string, content: string, chunkSize: number, chunkOverlap: number): ParsedFile {
232	  const chunks: ParsedFile['chunks'] = [];
233	  if (fileName.endsWith('.json')) {
234	    try {
235	      const arr = JSON.parse(content);
236	      if (Array.isArray(arr)) {
237	        arr.forEach((item: { id?: string; title?: string; text?: string }, idx: number) => {
238	          const text = item.text || item.title || '';
239	          if (!text) return;
240	          const subChunks = splitIntoChunks(text, chunkSize, chunkOverlap);
241	          subChunks.forEach((c, ci) => {
242	            chunks.push({
243	              id: `${item.id || idx}_${ci}`,
244	              text: c,
245	              fileName: item.title || fileName,
246	              chunkIndex: ci,
247	            });
248	          });
249	        });
250	      }
251	    } catch {
252	      const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
253	      textChunks.forEach((c, i) => {
254	        chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
255	      });
256	    }
257	  } else {
258	    const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
259	    textChunks.forEach((c, i) => {
260	      chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
261	    });
262	  }
263	  return { fileName, chunks };
264	}
