266	async function handleImport() {
267	  if (!state.currentCourse) { showToast('请先选择课程', 'error'); return; }
268	  if (!state.modelReady) { showToast('模型尚未加载完成', 'error'); return; }
269	
270	  const fileInput = document.getElementById('file-input') as HTMLInputElement;
271	  const files = fileInput?.files;
272	  if (!files || files.length === 0) { showToast('请选择文件', 'error'); return; }
273	
274	  const chunkSize = parseInt((document.getElementById('chunk-size') as HTMLInputElement)?.value || '300');
275	  const chunkOverlap = parseInt((document.getElementById('chunk-overlap') as HTMLInputElement)?.value || '50');
276	
277	  const progressArea = document.getElementById('import-progress-area');
278	  const statusText = document.getElementById('import-status-text');
279	  const progressFill = document.getElementById('import-progress-fill');
280	  const fileListEl = document.getElementById('import-file-list');
281	  if (progressArea) progressArea.style.display = 'block';
282	  if (fileListEl) fileListEl.innerHTML = '';
283	
284	  try {
285	    const allParsed: ParsedFile[] = [];
286	    for (const file of Array.from(files)) {
287	      const content = await file.text();
288	      const parsed = parseFile(file.name, content, chunkSize, chunkOverlap);
289	      allParsed.push(parsed);
290	      if (fileListEl) {
291	        const item = document.createElement('div');
292	        item.className = 'file-item';
293	        item.textContent = `${file.name} — ${parsed.chunks.length} 个分块`;
294	        fileListEl.appendChild(item);
295	      }
296	    }
297	
298	    const totalChunks = allParsed.reduce((sum, p) => sum + p.chunks.length, 0);
299	    if (totalChunks === 0) { showToast('未解析到任何内容', 'error'); return; }
300	
301	    if (statusText) statusText.textContent = `正在向量化 0/${totalChunks}...`;
302	    if (progressFill) progressFill.style.width = '0%';
303	
304	    const allChunks = allParsed.flatMap((p) => p.chunks);
305	    const batchSize = 16;
306	    const embedded: Array<typeof allChunks[0] & { embedding: number[] }> = [];
307	
308	    for (let i = 0; i < allChunks.length; i += batchSize) {
309	      const batch = allChunks.slice(i, i + batchSize);
310	      const texts = batch.map((c) => c.text);
311	      const vectors = await embedTexts(texts);
312	      batch.forEach((c, j) => {
313	        embedded.push({ ...c, embedding: vectors[j] });
314	      });
315	      const done = Math.min(i + batchSize, totalChunks);
316	      if (statusText) statusText.textContent = `正在向量化 ${done}/${totalChunks}...`;
317	      if (progressFill) progressFill.style.width = `${(done / totalChunks) * 80}%`;
318	    }
319	
320	    if (statusText) statusText.textContent = `正在写入 seekdb...`;
321	    if (progressFill) progressFill.style.width = '85%';
322	
323	    const importBatchSize = 50;
324	    for (let i = 0; i < embedded.length; i += importBatchSize) {
325	      const batch = embedded.slice(i, i + importBatchSize);
326	      await api.importChunks(
327	        state.currentCourse,
328	        batch.map((c) => ({
329	          id: c.id,
330	          text: c.text,
331	          embedding: c.embedding,
332	          fileName: c.fileName,
333	          chunkIndex: c.chunkIndex,
334	        }))
335	      );
336	      const done = Math.min(i + importBatchSize, embedded.length);
337	      if (progressFill) progressFill.style.width = `${85 + (done / embedded.length) * 15}%`;
338	    }
339	
340	    if (statusText) statusText.textContent = `导入完成: ${embedded.length} 个分块`;
341	    if (progressFill) progressFill.style.width = '100%';
342	    showToast(`成功导入 ${embedded.length} 个分块`, 'success');
343	    refreshCollections();
344	  } catch (e) {
345	    const msg = e instanceof Error ? e.message : String(e);
346	    showToast(`导入失败: ${msg}`, 'error');
347	    if (statusText) statusText.textContent = `导入失败: ${msg}`;
348	  }
349	}
