440	function highlightText(text: string, query: string): string {
441	  const words = query.split(/\s+/).filter(Boolean);
442	  let result = escapeHtml(text);
443	  for (const word of words) {
444	    const escaped = escapeHtml(word);
445	    const regex = new RegExp(`(${escaped.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
446	    result = result.replace(regex, '<mark>$1</mark>');
447	  }
448	  return result;
449	}
