import { api, type CollectionInfo, type SearchResult, type ReviewEntry } from './api';
import { embedTexts, embedSingle, ensureModelReady } from './embedding';
import { setStatus, showToast, loadState, saveState, type AppState } from './state';

const state: AppState = {
  currentCourse: null,
  collections: [],
  reviewProgress: new Map(),
  lastSearchTime: null,
  modelReady: false,
  importProgress: null,
};

export function initUI() {
  const saved = loadState();
  if (saved.currentCourse) state.currentCourse = saved.currentCourse;
  setupNav();
  renderCourses();
  renderImport();
  renderSearch();
  renderReview();
  initModel();
}

function setupNav() {
  document.querySelectorAll('.nav-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.nav-btn').forEach((b) => b.classList.remove('active'));
      document.querySelectorAll('.tab-content').forEach((t) => t.classList.remove('active'));
      btn.classList.add('active');
      const tab = btn.getAttribute('data-tab');
      if (tab) {
        document.getElementById(`tab-${tab}`)?.classList.add('active');
        if (tab === 'review') refreshWeakPoints();
        if (tab === 'courses') refreshCollections();
      }
    });
  });
}

async function initModel() {
  setStatus('正在加载向量化模型...');
  try {
    await ensureModelReady();
    state.modelReady = true;
    setStatus('模型就绪');
    showToast('向量化模型加载完成', 'success');
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    setStatus('模型加载失败: ' + msg);
    showToast('模型加载失败，请检查 /models 目录', 'error');
  }
}

// ─── Courses Tab ───

function renderCourses() {
  const el = document.getElementById('tab-courses');
  if (!el) return;
  el.innerHTML = `
    <div class="card">
      <h3>新建课程</h3>
      <div class="row">
        <input type="text" id="new-course-id" placeholder="课程 ID（英文，如 math101）" />
        <button class="primary" id="btn-create-course">创建</button>
      </div>
    </div>
    <div class="card">
      <h3>课程列表</h3>
      <div id="course-list"><div class="empty-hint">加载中...</div></div>
    </div>
  `;
  document.getElementById('btn-create-course')?.addEventListener('click', createCourse);
  refreshCollections();
}

async function refreshCollections() {
  try {
    state.collections = await api.listCollections();
    renderCourseList();
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    const el = document.getElementById('course-list');
    if (el) el.innerHTML = `<div class="empty-hint">加载失败: ${msg}</div>`;
  }
}

function renderCourseList() {
  const el = document.getElementById('course-list');
  if (!el) return;
  if (state.collections.length === 0) {
    el.innerHTML = '<div class="empty-hint">暂无课程，请先创建</div>';
    return;
  }
  el.innerHTML = '';
  for (const col of state.collections) {
    const div = document.createElement('div');
    div.className = 'card';
    const isCurrent = state.currentCourse === col.courseId;
    div.innerHTML = `
      <div class="row" style="margin-bottom:0">
        <div style="flex:2">
          <h3>${col.courseId} ${isCurrent ? '<span class="badge badge-mastery-2">当前</span>' : ''}</h3>
          <div class="collection-info">
            <span>文档: ${col.docCount}</span>
            <span>分块: ${col.chunkCount}</span>
            <span>维度: ${col.dimension}</span>
          </div>
        </div>
        <div style="flex:0;display:flex;gap:6px">
          <button class="small" data-action="switch" data-course="${col.courseId}">${isCurrent ? '已选中' : '切换'}</button>
          <button class="danger" data-action="delete" data-course="${col.courseId}">删除</button>
        </div>
      </div>
    `;
    el.appendChild(div);
  }
  el.querySelectorAll('[data-action="switch"]').forEach((btn) => {
    btn.addEventListener('click', () => {
      state.currentCourse = btn.getAttribute('data-course') || null;
      saveState(state);
      refreshCollections();
      showToast('已切换课程', 'success');
    });
  });
  el.querySelectorAll('[data-action="delete"]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const courseId = btn.getAttribute('data-course') || '';
      if (confirm(`确定删除课程「${courseId}」？此操作不可恢复。`)) {
        deleteCourse(courseId);
      }
    });
  });
}

async function createCourse() {
  const input = document.getElementById('new-course-id') as HTMLInputElement;
  const courseId = input?.value.trim();
  if (!courseId) { showToast('请输入课程 ID', 'error'); return; }
  if (!/^[a-zA-Z0-9_-]+$/.test(courseId)) { showToast('课程 ID 只能包含英文、数字、下划线和短横线', 'error'); return; }
  try {
    setStatus(`正在创建课程 ${courseId}...`);
    await api.createCollection(courseId);
    state.currentCourse = courseId;
    saveState(state);
    input.value = '';
    showToast(`课程「${courseId}」创建成功`, 'success');
    setStatus('就绪');
    refreshCollections();
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    showToast(`创建失败: ${msg}`, 'error');
    setStatus('就绪');
  }
}

async function deleteCourse(courseId: string) {
  try {
    setStatus(`正在删除课程 ${courseId}...`);
    await api.deleteCollection(courseId);
    if (state.currentCourse === courseId) {
      state.currentCourse = null;
      saveState(state);
    }
    showToast(`课程「${courseId}」已删除`, 'success');
    setStatus('就绪');
    refreshCollections();
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    showToast(`删除失败: ${msg}`, 'error');
    setStatus('就绪');
  }
}

// ─── Import Tab ───

function renderImport() {
  const el = document.getElementById('tab-import');
  if (!el) return;
  el.innerHTML = `
    <div class="card">
      <h3>导入笔记</h3>
      <p class="label">支持 .md / .txt / .json（数组格式 {id, title, text}）</p>
      <div class="config-row">
        <label><span>分块大小（字符）</span><input type="number" id="chunk-size" value="300" min="50" max="2000" /></label>
        <label><span>重叠（字符）</span><input type="number" id="chunk-overlap" value="50" min="0" max="500" /></label>
      </div>
      <div class="row">
        <input type="file" id="file-input" multiple accept=".md,.txt,.json" style="flex:2" />
        <button class="primary" id="btn-import" ${!state.currentCourse ? 'disabled' : ''}>开始导入</button>
      </div>
      <div id="import-progress-area" style="display:none">
        <div class="label" id="import-status-text">准备中...</div>
        <div class="progress-bar"><div class="fill" id="import-progress-fill" style="width:0%"></div></div>
      </div>
      <div id="import-file-list" class="file-list"></div>
    </div>
  `;
  document.getElementById('btn-import')?.addEventListener('click', handleImport);
}

function splitIntoChunks(text: string, size: number, overlap: number): string[] {
  const sentences = text.match(/[^。！？.!?\n]+[。！？.!?\n]?/g) || [text];
  const chunks: string[] = [];
  let current = '';
  for (const sentence of sentences) {
    if (current.length + sentence.length > size && current.length > 0) {
      chunks.push(current.trim());
      const words = current.split(/\s+/);
      let keep = '';
      let keepLen = 0;
      for (let i = words.length - 1; i >= 0; i--) {
        if (keepLen + words[i].length > overlap) break;
        keep = words[i] + ' ' + keep;
        keepLen += words[i].length + 1;
      }
      current = keep.trim() + sentence;
    } else {
      current += sentence;
    }
  }
  if (current.trim()) chunks.push(current.trim());
  return chunks;
}

interface ParsedFile {
  fileName: string;
  chunks: Array<{ id: string; text: string; fileName: string; chunkIndex: number }>;
}

function parseFile(fileName: string, content: string, chunkSize: number, chunkOverlap: number): ParsedFile {
  const chunks: ParsedFile['chunks'] = [];
  if (fileName.endsWith('.json')) {
    try {
      const arr = JSON.parse(content);
      if (Array.isArray(arr)) {
        arr.forEach((item: { id?: string; title?: string; text?: string }, idx: number) => {
          const text = item.text || item.title || '';
          if (!text) return;
          const subChunks = splitIntoChunks(text, chunkSize, chunkOverlap);
          subChunks.forEach((c, ci) => {
            chunks.push({
              id: `${item.id || idx}_${ci}`,
              text: c,
              fileName: item.title || fileName,
              chunkIndex: ci,
            });
          });
        });
      }
    } catch {
      const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
      textChunks.forEach((c, i) => {
        chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
      });
    }
  } else {
    const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
    textChunks.forEach((c, i) => {
      chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
    });
  }
  return { fileName, chunks };
}

async function handleImport() {
  if (!state.currentCourse) { showToast('请先选择课程', 'error'); return; }
  if (!state.modelReady) { showToast('模型尚未加载完成', 'error'); return; }

  const fileInput = document.getElementById('file-input') as HTMLInputElement;
  const files = fileInput?.files;
  if (!files || files.length === 0) { showToast('请选择文件', 'error'); return; }

  const chunkSize = parseInt((document.getElementById('chunk-size') as HTMLInputElement)?.value || '300');
  const chunkOverlap = parseInt((document.getElementById('chunk-overlap') as HTMLInputElement)?.value || '50');

  const progressArea = document.getElementById('import-progress-area');
  const statusText = document.getElementById('import-status-text');
  const progressFill = document.getElementById('import-progress-fill');
  const fileListEl = document.getElementById('import-file-list');
  if (progressArea) progressArea.style.display = 'block';
  if (fileListEl) fileListEl.innerHTML = '';

  try {
    const allParsed: ParsedFile[] = [];
    for (const file of Array.from(files)) {
      const content = await file.text();
      const parsed = parseFile(file.name, content, chunkSize, chunkOverlap);
      allParsed.push(parsed);
      if (fileListEl) {
        const item = document.createElement('div');
        item.className = 'file-item';
        item.textContent = `${file.name} — ${parsed.chunks.length} 个分块`;
        fileListEl.appendChild(item);
      }
    }

    const totalChunks = allParsed.reduce((sum, p) => sum + p.chunks.length, 0);
    if (totalChunks === 0) { showToast('未解析到任何内容', 'error'); return; }

    if (statusText) statusText.textContent = `正在向量化 0/${totalChunks}...`;
    if (progressFill) progressFill.style.width = '0%';

    const allChunks = allParsed.flatMap((p) => p.chunks);
    const batchSize = 16;
    const embedded: Array<typeof allChunks[0] & { embedding: number[] }> = [];

    for (let i = 0; i < allChunks.length; i += batchSize) {
      const batch = allChunks.slice(i, i + batchSize);
      const texts = batch.map((c) => c.text);
      const vectors = await embedTexts(texts);
      batch.forEach((c, j) => {
        embedded.push({ ...c, embedding: vectors[j] });
      });
      const done = Math.min(i + batchSize, totalChunks);
      if (statusText) statusText.textContent = `正在向量化 ${done}/${totalChunks}...`;
      if (progressFill) progressFill.style.width = `${(done / totalChunks) * 80}%`;
    }

    if (statusText) statusText.textContent = `正在写入 seekdb...`;
    if (progressFill) progressFill.style.width = '85%';

    const importBatchSize = 50;
    for (let i = 0; i < embedded.length; i += importBatchSize) {
      const batch = embedded.slice(i, i + importBatchSize);
      await api.importChunks(
        state.currentCourse,
        batch.map((c) => ({
          id: c.id,
          text: c.text,
          embedding: c.embedding,
          fileName: c.fileName,
          chunkIndex: c.chunkIndex,
        }))
      );
      const done = Math.min(i + importBatchSize, embedded.length);
      if (progressFill) progressFill.style.width = `${85 + (done / embedded.length) * 15}%`;
    }

    if (statusText) statusText.textContent = `导入完成: ${embedded.length} 个分块`;
    if (progressFill) progressFill.style.width = '100%';
    showToast(`成功导入 ${embedded.length} 个分块`, 'success');
    refreshCollections();
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    showToast(`导入失败: ${msg}`, 'error');
    if (statusText) statusText.textContent = `导入失败: ${msg}`;
  }
}

// ─── Search Tab ───

function renderSearch() {
  const el = document.getElementById('tab-search');
  if (!el) return;
  el.innerHTML = `
    <div class="card">
      <h3>混合检索</h3>
      <div class="row">
        <input type="text" id="search-input" placeholder="输入问题或关键词..." />
        <button class="primary" id="btn-search">检索</button>
      </div>
      <div id="search-timing" class="label" style="margin-top:4px"></div>
    </div>
    <div id="search-results"></div>
  `;
  document.getElementById('btn-search')?.addEventListener('click', handleSearch);
  document.getElementById('search-input')?.addEventListener('keydown', (e) => {
    if ((e as KeyboardEvent).key === 'Enter') handleSearch();
  });
}

async function handleSearch() {
  if (!state.currentCourse) { showToast('请先选择课程', 'error'); return; }
  if (!state.modelReady) { showToast('模型尚未加载完成', 'error'); return; }

  const input = document.getElementById('search-input') as HTMLInputElement;
  const query = input?.value.trim();
  if (!query) { showToast('请输入查询内容', 'error'); return; }

  const resultsEl = document.getElementById('search-results');
  const timingEl = document.getElementById('search-timing');
  if (resultsEl) resultsEl.innerHTML = '<div class="empty-hint">检索中...</div>';

  try {
    const t0 = performance.now();
    const vector = await embedSingle(query);
    const t1 = performance.now();

    const { results } = await api.search(state.currentCourse, query, vector, 10);
    const t2 = performance.now();

    state.lastSearchTime = {
      embed: Math.round(t1 - t0),
      search: Math.round(t2 - t1),
      total: Math.round(t2 - t0),
    };
    if (timingEl) {
      timingEl.textContent = `向量化: ${state.lastSearchTime.embed}ms | seekdb 检索: ${state.lastSearchTime.search}ms | 总计: ${state.lastSearchTime.total}ms`;
    }

    if (!resultsEl) return;
    if (results.length === 0) {
      resultsEl.innerHTML = '<div class="empty-hint">未找到相关结果</div>';
      return;
    }

    resultsEl.innerHTML = '';
    for (const r of results) {
      const div = document.createElement('div');
      div.className = 'search-result';
      const textHtml = highlightText(r.text || '', query);
      const reviewId = `${state.currentCourse}::${r.id}`;
      div.innerHTML = `
        <div class="score">得分: ${(r.score ?? 0).toFixed(4)}</div>
        <div class="text">${textHtml}</div>
        <div class="meta">来源: ${r.file_name || '未知'} | 分块: ${r.chunk_index ?? '-'} | ID: ${r.id}</div>
        <div class="actions">
          <button class="small btn-add-review" data-chunk-id="${r.id}" data-text="${encodeURIComponent(r.text || '')}" data-file="${encodeURIComponent(r.file_name || '')}">加入复习</button>
        </div>
      `;
      resultsEl.appendChild(div);
    }

    resultsEl.querySelectorAll('.btn-add-review').forEach((btn) => {
      btn.addEventListener('click', () => {
        const chunkId = btn.getAttribute('data-chunk-id') || '';
        const text = decodeURIComponent(btn.getAttribute('data-text') || '');
        const fileName = decodeURIComponent(btn.getAttribute('data-file') || '');
        addReview(chunkId, text, fileName);
      });
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    showToast(`检索失败: ${msg}`, 'error');
    if (resultsEl) resultsEl.innerHTML = `<div class="empty-hint">检索失败: ${msg}</div>`;
  }
}

function highlightText(text: string, query: string): string {
  const words = query.split(/\s+/).filter(Boolean);
  let result = escapeHtml(text);
  for (const word of words) {
    const escaped = escapeHtml(word);
    const regex = new RegExp(`(${escaped.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    result = result.replace(regex, '<mark>$1</mark>');
  }
  return result;
}

function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

async function addReview(chunkId: string, text: string, fileName: string) {
  if (!state.currentCourse) return;
  try {
    await api.addReview(state.currentCourse, chunkId, text, fileName);
    showToast('已加入复习', 'success');
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    showToast(`加入复习失败: ${msg}`, 'error');
  }
}

// ─── Review Tab ───

function renderReview() {
  const el = document.getElementById('tab-review');
  if (!el) return;
  el.innerHTML = `
    <div class="card">
      <h3>薄弱知识点 Top 5</h3>
      <div id="weak-points-list"><div class="empty-hint">加载中...</div></div>
    </div>
    <div class="card">
      <h3>全部复习记录</h3>
      <div id="all-progress-list"><div class="empty-hint">加载中...</div></div>
    </div>
  `;
}

async function refreshWeakPoints() {
  if (!state.currentCourse) {
    const el = document.getElementById('weak-points-list');
    if (el) el.innerHTML = '<div class="empty-hint">请先选择课程</div>';
    return;
  }
  try {
    const weakPoints = await api.getWeakPoints(state.currentCourse);
    const allProgress = await api.getAllProgress(state.currentCourse);
    renderWeakPointsList(weakPoints);
    renderAllProgressList(allProgress);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    const el = document.getElementById('weak-points-list');
    if (el) el.innerHTML = `<div class="empty-hint">加载失败: ${msg}</div>`;
  }
}

function renderWeakPointsList(items: ReviewEntry[]) {
  const el = document.getElementById('weak-points-list');
  if (!el) return;
  if (items.length === 0) {
    el.innerHTML = '<div class="empty-hint">暂无复习记录</div>';
    return;
  }
  el.innerHTML = '';
  for (const item of items) {
    const div = document.createElement('div');
    div.className = 'weak-item';
    const masteryLabel = item.mastery === 2 ? '会' : item.mastery === 1 ? '模糊' : '不会';
    const masteryClass = `badge-mastery-${item.mastery}`;
    div.innerHTML = `
      <div class="info">
        <div class="text-preview">${escapeHtml((item.text || '').slice(0, 100))}${(item.text || '').length > 100 ? '...' : ''}</div>
        <div class="meta-line">来源: ${escapeHtml(item.file_name || '未知')} | 复习 ${item.review_count} 次 | <span class="badge ${masteryClass}">${masteryLabel}</span></div>
      </div>
      <div style="display:flex;gap:6px;align-items:center">
        <div class="mastery-btns" data-review-id="${item.id}" data-current-mastery="${item.mastery}">
          <button data-mastery="2" title="会">会</button>
          <button data-mastery="1" title="模糊">模糊</button>
          <button data-mastery="0" title="不会">不会</button>
        </div>
      </div>
    `;
    el.appendChild(div);
  }

  el.querySelectorAll('.mastery-btns').forEach((group) => {
    const reviewId = group.getAttribute('data-review-id') || '';
    const current = parseInt(group.getAttribute('data-current-mastery') || '0');
    group.querySelectorAll('button').forEach((btn) => {
      const val = parseInt(btn.getAttribute('data-mastery') || '0');
      if (val === current) btn.classList.add(`selected-mastery-${val}`);
      btn.addEventListener('click', async () => {
        try {
          await api.updateMastery(reviewId, val);
          showToast('掌握度已更新', 'success');
          refreshWeakPoints();
        } catch (e) {
          const msg = e instanceof Error ? e.message : String(e);
          showToast(`更新失败: ${msg}`, 'error');
        }
      });
    });
  });
}

function renderAllProgressList(items: ReviewEntry[]) {
  const el = document.getElementById('all-progress-list');
  if (!el) return;
  if (items.length === 0) {
    el.innerHTML = '<div class="empty-hint">暂无复习记录</div>';
    return;
  }
  el.innerHTML = '';
  for (const item of items) {
    const div = document.createElement('div');
    div.className = 'weak-item';
    const masteryLabel = item.mastery === 2 ? '会' : item.mastery === 1 ? '模糊' : '不会';
    const masteryClass = `badge-mastery-${item.mastery}`;
    div.innerHTML = `
      <div class="info">
        <div class="text-preview">${escapeHtml((item.text || '').slice(0, 80))}${(item.text || '').length > 80 ? '...' : ''}</div>
        <div class="meta-line">来源: ${escapeHtml(item.file_name || '未知')} | 复习 ${item.review_count} 次 | <span class="badge ${masteryClass}">${masteryLabel}</span> | ${item.last_reviewed || ''}</div>
      </div>
    `;
    el.appendChild(div);
  }
}

